import java.math.BigInteger
import java.util.Scanner
import kotlin.math.abs
import kotlin.math.log10

const val MOD = 1_000_000_007
const val MAX_INT = Int.MAX_VALUE
const val MIN_INT = Int.MIN_VALUE
const val MAX_LONG = Long.MAX_VALUE
const val MIN_LONG = Long.MIN_VALUE

fun main() {
    val scanner = Scanner(System.`in`)
    var t = scanner.nextInt()

    while (t > 0) {
        t--
        val n = scanner.nextLong()
        val k = scanner.nextLong()

        val base = BigInteger.valueOf(n)
        val exp = BigInteger.valueOf(k)
        val mod = BigInteger.valueOf(MOD)

        val ans = base.modPow(exp, mod).longValue()
        println(ans)
    }
}

fun reversed(s: String): String = s.reversed()

fun divCeil(num: Int, div: Int): Int {
    var quot = num / div
    if (num % div != 0) quot++
    return quot
}

fun min(vararg nums: Int): Int {
    var minimum = nums[0]
    for (num in nums) {
        if (num < minimum) minimum = num
    }
    return minimum
}

fun max(vararg nums: Int): Int {
    var maximum = nums[0]
    for (num in nums) {
        if (num > maximum) maximum = num
    }
    return maximum
}

fun isPrime(num: Int): Boolean {
    if (num == 2 || num == 3) return true
    if (num <= 1 || num % 2 == 0 || num % 3 == 0) return false
    var i = 5
    while (i * i <= num) {
        if (num % i == 0 || num % (i + 2) == 0) return false
        i += 6
    }
    return true
}

fun gcd(a: Int, b: Int): Int {
    var aa = a
    var bb = b
    while (bb != 0) {
        val temp = bb
        bb = aa % bb
        aa = temp
    }
    return aa
}

fun lcm(a: Int, b: Int): Int = abs(a) / gcd(a, b) * abs(b)

fun digitAt(num: Int, pos: Int): Int {
    if (num == 0) return 0
    val absNum = abs(num)
    val s = absNum.toString()
    val lenNum = s.length
    if (pos < 0 || pos >= lenNum) {
        throw IndexOutOfBoundsException("Out of bound access for digit. Position passed $pos, number $absNum")
    }
    return s[lenNum - 1 - pos] - '0'
}

